import { EARTH_RADIUS_M } from "./geometry.js";
import type { RasterGrid } from "./raster-grid.js";

/**
 * Per-cell heat-model features. This is a line-for-line port of ml/urbanheat_ml/features.py, whose module docstring is
 * the specification; a golden fixture generated by the Python code is compared against this implementation in the tests,
 * so the two cannot drift apart silently.
 */

export const DIST_CAP_M = 5000;
export const RADII_M = [150, 500, 1000] as const;

export const FEATURE_NAMES = [
  "canopy_pct",
  "impervious_pct",
  "canopy_mean_150m",
  "canopy_mean_500m",
  "canopy_mean_1000m",
  "impervious_mean_150m",
  "impervious_mean_500m",
  "impervious_mean_1000m",
  "elevation_m",
  "elev_rel_1000m",
  "dist_water_m",
  "water_frac_500m",
] as const;
export type FeatureName = (typeof FEATURE_NAMES)[number];

export interface CellSize {
  dxM: number;
  dyM: number;
}

/** Ground size of a cell in metres (spherical Earth) at the grid's centre latitude. */
export function cellSizeM(resLon: number, resLat: number, latCenter: number): CellSize {
  const mPerDeg = (EARTH_RADIUS_M * Math.PI) / 180;
  return { dxM: resLon * mPerDeg * Math.cos((latCenter * Math.PI) / 180), dyM: resLat * mPerDeg };
}

/** Window half-widths (cells) for a ground radius: at least 1, rounding half up (Math.round and Python's round differ at .5). */
export function halfWidths(radiusM: number, size: CellSize): [kx: number, ky: number] {
  return [Math.max(1, Math.floor(radiusM / size.dxM + 0.5)), Math.max(1, Math.floor(radiusM / size.dyM + 0.5))];
}

/** Sum over the (2ky+1) x (2kx+1) window around every cell, clipped at the edges, via an integral image. */
function windowSums(a: Float64Array, w: number, h: number, kx: number, ky: number): Float64Array {
  const stride = w + 1;
  const ii = new Float64Array((h + 1) * stride);
  for (let r = 0; r < h; r++) {
    let rowSum = 0;
    for (let c = 0; c < w; c++) {
      rowSum += a[r * w + c]!;
      ii[(r + 1) * stride + c + 1] = ii[r * stride + c + 1]! + rowSum;
    }
  }
  const out = new Float64Array(w * h);
  for (let r = 0; r < h; r++) {
    const r0 = Math.max(r - ky, 0);
    const r1 = Math.min(r + ky + 1, h);
    for (let c = 0; c < w; c++) {
      const c0 = Math.max(c - kx, 0);
      const c1 = Math.min(c + kx + 1, w);
      out[r * w + c] = ii[r1 * stride + c1]! - ii[r0 * stride + c1]! - ii[r1 * stride + c0]! + ii[r0 * stride + c0]!;
    }
  }
  return out;
}

/** Mean over the window of valid (non-NaN, and `valid` if given) cells; NaN where the window holds none. */
export function boxMean(a: ArrayLike<number>, w: number, h: number, kx: number, ky: number, valid?: ArrayLike<number | boolean>): Float64Array {
  const n = w * h;
  const vals = new Float64Array(n);
  const ok = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    const v = a[i]!;
    if (!Number.isNaN(v) && (valid === undefined || valid[i])) {
      vals[i] = v;
      ok[i] = 1;
    }
  }
  const total = windowSums(vals, w, h, kx, ky);
  const count = windowSums(ok, w, h, kx, ky);
  return total.map((t, i) => (count[i]! > 0 ? t / count[i]! : NaN));
}

/** Share of window cells where `mask` holds (the window is clipped at the grid edge, and the denominator is its clipped size). */
export function boxFraction(mask: ArrayLike<number | boolean>, w: number, h: number, kx: number, ky: number): Float64Array {
  const m = Float64Array.from({ length: w * h }, (_, i) => (mask[i] ? 1 : 0));
  const num = windowSums(m, w, h, kx, ky);
  const den = windowSums(new Float64Array(w * h).fill(1), w, h, kx, ky);
  return num.map((v, i) => v / den[i]!);
}

const INF = 1e20;

/**
 * 1-D squared Euclidean distance transform with sample spacing `s` (Felzenszwalb & Huttenlocher, "Distance Transforms of
 * Sampled Functions"): the lower envelope of the parabolas rooted at each sample, written into `d`. `v` holds the parabola
 * roots on the envelope and `z` the boundaries between them (z[0] = -Infinity keeps the stack from emptying).
 */
function edt1d(f: Float64Array, n: number, s: number, d: Float64Array, v: Int32Array, z: Float64Array): void {
  let k = 0;
  v[0] = 0;
  z[0] = -Infinity;
  z[1] = Infinity;
  for (let q = 1; q < n; q++) {
    let boundary: number;
    for (;;) {
      const p = v[k]!;
      boundary = (f[q]! + (q * s) ** 2 - (f[p]! + (p * s) ** 2)) / (2 * q * s - 2 * p * s);
      if (boundary > z[k]!) break;
      k--; // the new parabola hides the top of the stack
    }
    k++;
    v[k] = q;
    z[k] = boundary;
    z[k + 1] = Infinity;
  }
  k = 0;
  for (let q = 0; q < n; q++) {
    while (z[k + 1]! < q * s) k++;
    d[q] = ((q - v[k]!) * s) ** 2 + f[v[k]!]!;
  }
}

/** Euclidean distance (m) from each cell to the nearest `mask` cell, capped; `cap` everywhere when the mask is empty. */
export function distanceToMask(mask: ArrayLike<number | boolean>, w: number, h: number, size: CellSize, cap = DIST_CAP_M): Float64Array {
  const n = w * h;
  let any = false;
  const g = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    if (mask[i]) any = true;
    else g[i] = INF;
  }
  if (!any) return new Float64Array(n).fill(cap);
  const m = Math.max(w, h);
  const f = new Float64Array(m);
  const d = new Float64Array(m);
  const v = new Int32Array(m);
  const z = new Float64Array(m + 1);
  // pass 1: along each column (spacing dy), pass 2: along each row (spacing dx) on the result
  for (let c = 0; c < w; c++) {
    for (let r = 0; r < h; r++) f[r] = g[r * w + c]!;
    edt1d(f, h, size.dyM, d, v, z);
    for (let r = 0; r < h; r++) g[r * w + c] = d[r]!;
  }
  for (let r = 0; r < h; r++) {
    for (let c = 0; c < w; c++) f[c] = g[r * w + c]!;
    edt1d(f, w, size.dxM, d, v, z);
    for (let c = 0; c < w; c++) g[r * w + c] = d[c]!;
  }
  return g.map((sq) => Math.min(Math.sqrt(sq), cap));
}

export interface FeatureInputs {
  canopy: RasterGrid;
  impervious: RasterGrid;
  elevation: RasterGrid;
  /** Open-water mask, row-major like the grids (1/true = water). */
  water: ArrayLike<number | boolean>;
}

export interface FeatureStack {
  width: number;
  height: number;
  names: readonly FeatureName[];
  /** One array per name (same order), row-major, NaN where an input was missing. */
  data: Record<FeatureName, Float64Array>;
}

/** All FEATURE_NAMES for every cell. See the specification in ml/urbanheat_ml/features.py. */
export function buildFeatures(inp: FeatureInputs, size: CellSize): FeatureStack {
  const { canopy, impervious, elevation } = inp;
  const { width: w, height: h } = canopy;
  for (const g of [impervious, elevation]) {
    if (g.width !== w || g.height !== h) throw new RangeError("feature inputs must share one grid");
  }
  const n = w * h;
  const land = Float64Array.from({ length: n }, (_, i) => (inp.water[i] ? 0 : 1));
  const can = Float64Array.from(canopy.data);
  const imp = Float64Array.from(impervious.data);
  const elev = Float64Array.from(elevation.data);
  const data = { canopy_pct: can, impervious_pct: imp, elevation_m: elev } as Record<string, Float64Array>;
  for (const r of RADII_M) {
    const [kx, ky] = halfWidths(r, size);
    data[`canopy_mean_${r}m`] = boxMean(can, w, h, kx, ky, land);
    data[`impervious_mean_${r}m`] = boxMean(imp, w, h, kx, ky, land);
  }
  const [kx1, ky1] = halfWidths(1000, size);
  const mean1k = boxMean(elev, w, h, kx1, ky1);
  data.elev_rel_1000m = elev.map((e, i) => e - mean1k[i]!);
  data.dist_water_m = distanceToMask(inp.water, w, h, size);
  const [kx5, ky5] = halfWidths(500, size);
  data.water_frac_500m = boxFraction(inp.water, w, h, kx5, ky5);
  return { width: w, height: h, names: FEATURE_NAMES, data: data as Record<FeatureName, Float64Array> };
}
